# ============================================================
# 12. FINAL MAP PREVIEW
# ============================================================

vis = (
    final_class
    .updateMask(valid_mask)
    .visualize(
        min=1,
        max=4,
        palette=[
            "2CA25F",
            "FEE08B",
            "F46D43",
            "A50026"
        ],
        forceRgbOutput=True
    )
)

thumb_url = vis.getThumbURL({
    "region":
        core_img.geometry().bounds(),

    "dimensions":
        1400,

    "format":
        "png"
})

